sp_widget.client_script:
api.controller = function ($scope, $rootScope) {
  var c = this;

  c.loading = false;

  c.performAction = function (action) {
    c.loading = true;
    c.data.message = "";
    c.data.success = false;
    c.data.error = false;
    c.server.get({ action: action, sys_id: c.data.visit.sys_id }).then(
      function (r) {
        c.data = r.data;
        c.loading = false;
        // Notify guest list to refresh
        $rootScope.$broadcast("sp.visit.updated", { sys_id: c.data.visit.sys_id });
      },
      function () {
        c.loading = false;
      }
    );
  };

  c.goBack = function () {
    window.location.href = "?id=x_1085196_visita_0_visits";
  };

  c.getStatusClass = function (status) {
    var map = {
      pending: "label-warning",
      approved: "label-info",
      checked_in: "label-success",
      checked_out: "label-default",
      cancelled: "label-danger"
    };
    return map[status] || "label-default";
  };

  c.getStatusLabel = function (status) {
    var map = {
      pending: "Pending",
      approved: "Approved",
      checked_in: "Checked In",
      checked_out: "Checked Out",
      cancelled: "Cancelled"
    };
    return map[status] || status;
  };

  c.canApprove = function () {
    return c.data.visit && c.data.visit.status === "pending";
  };
  c.canCheckIn = function () {
    return c.data.visit && (c.data.visit.status === "approved" || c.data.visit.status === "pending");
  };
  c.canCheckOut = function () {
    return c.data.visit && c.data.visit.status === "checked_in";
  };
  c.canCancel = function () {
    return c.data.visit && c.data.visit.status !== "cancelled" && c.data.visit.status !== "checked_out";
  };
};

sp_widget.css:
/* Card */
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 24px;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon { margin-right: 8px; color: $brand-primary; font-size: 16px; }
.sp-card-body { padding: 24px; flex: 1 1 auto; }

/* Section titles */
.sp-section-title {
  font-size: $font-size-base;
  font-weight: 600;
  color: $text-color;
  margin: 0 0 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid $border-tertiary;
}

/* Description list */
.sp-dl dt {
  font-size: $font-size-small;
  color: $text-muted;
  font-weight: 500;
}
.sp-dl dd {
  font-size: $font-size-base;
  color: $text-color;
  margin-bottom: 8px;
}

/* Buttons */
.sp-btn-primary, .sp-btn-secondary, .sp-btn-danger {
  height: 44px;
  padding: 0 20px;
  border-radius: $border-radius-base;
  font-size: $font-size-base;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background 0.15s, box-shadow 0.15s;
  cursor: pointer;
  border: none;
}
.sp-btn-primary {
  background: $brand-primary;
  color: $btn-primary-color;
  &:hover:not(:disabled) {
    background: $brand-primary-dark;
    box-shadow: 0 2px 8px rgba($brand-primary, 0.3);
    color: $btn-primary-color;
  }
  &:disabled { opacity: 0.55; cursor: not-allowed; }
}
.sp-btn-secondary {
  background: $background-primary;
  border: 1px solid $border-tertiary;
  color: $text-color;
  &:hover { background: $background-secondary; }
}
.sp-btn-danger {
  background: $brand-danger;
  color: $btn-primary-color;
  &:hover { background: darken($brand-danger, 8%); }
}
.sp-btn-group {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 24px;
  flex-wrap: wrap;
}

/* Empty State */
.sp-empty-state { padding: 64px 24px; }
.sp-empty-icon {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  opacity: 0.35;
  color: $text-muted;
}
.sp-empty-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 8px;
}

sp_widget.script:
(function () {
  data.visit = null;
  data.message = "";
  data.success = false;
  data.error = false;

  try {
    var sysId = "";
    if (input && input.sys_id) {
      sysId = input.sys_id;
    } else {
      sysId = $sp.getParameter("sys_id");
    }

    // Handle actions
    if (input && input.action && sysId) {
      var actionGr = new GlideRecord("x_1085196_visita_0_visit");
      if (actionGr.get(sysId)) {
        if (input.action === "approve" && actionGr.getValue("status") === "pending") {
          actionGr.setValue("status", "approved");
          actionGr.update();
          data.success = true;
          data.message = "Visit approved successfully.";
        } else if (input.action === "check_in" && (actionGr.getValue("status") === "approved" || actionGr.getValue("status") === "pending")) {
          actionGr.setValue("status", "checked_in");
          actionGr.update();
          data.success = true;
          data.message = "Visitor checked in successfully.";
        } else if (input.action === "check_out" && actionGr.getValue("status") === "checked_in") {
          actionGr.setValue("status", "checked_out");
          actionGr.update();
          data.success = true;
          data.message = "Visitor checked out successfully.";
        } else if (input.action === "cancel" && actionGr.getValue("status") !== "cancelled" && actionGr.getValue("status") !== "checked_out") {
          actionGr.setValue("status", "cancelled");
          actionGr.update();
          data.success = true;
          data.message = "Visit cancelled.";
        } else {
          data.error = true;
          data.message = "Action not allowed for the current visit status.";
        }
      }
    }

    // Load visit details
    if (sysId) {
      var gr = new GlideRecord("x_1085196_visita_0_visit");
      gr.setLimit(1);
      if (gr.get(sysId)) {
        data.visit = {
          sys_id: gr.getUniqueValue(),
          number: gr.getValue("number"),
          visitor_name: gr.getValue("visitor_name"),
          visitor_email: gr.getValue("visitor_email"),
          visitor_phone: gr.getValue("visitor_phone"),
          visitor_company: gr.getValue("visitor_company"),
          host: gr.getDisplayValue("host") + "",
          status: gr.getValue("status"),
          visit_date: gr.getDisplayValue("visit_date") + "",
          check_in_time: gr.getDisplayValue("check_in_time") + "",
          check_out_time: gr.getDisplayValue("check_out_time") + "",
          purpose: gr.getValue("purpose"),
          number_of_guests: gr.getValue("number_of_guests"),
          notes: gr.getValue("notes")
        };
      }
    }
  } catch (e) {
    gs.error("Visit Detail error: " + e.message);
    data.error = true;
    data.message = "An error occurred loading visit details.";
  }
})();
